@page "/category/{Slug}"

<PageTitle>@CategoryName - RecipeShare</PageTitle>

<h1>@CategoryName</h1>

@if (recipes is not null && recipes.Count > 0)
{
    <div class="row">
        @foreach (var recipe in recipes)
        {
            <div class="col-md-6 mb-3">
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">@recipe.Description</p>
                        <a href="/recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}
else
{
    <p>No recipes found in this category.</p>
}

<a href="/" class="btn btn-secondary mt-3">← Back to Categories</a>

@code {
    [Parameter]
    public string Slug { get; set; } = "";

    private string CategoryName => Slug switch
    {
        "appetizers" => "Appetizers",
        "main-courses" => "Main Courses",
        "desserts" => "Desserts",
        _ => "Unknown Category"
    };

    private List<RecipeInfo>? recipes;

    protected override void OnParametersSet()
    {
        recipes = GetRecipesForCategory(Slug);
    }

    private static List<RecipeInfo> GetRecipesForCategory(string slug) => slug switch
    {
        "appetizers" => new()
        {
            new(1, "Bruschetta", "Classic Italian toasted bread with tomatoes and basil."),
            new(2, "Spinach Dip", "Creamy spinach and artichoke dip served warm."),
        },
        "main-courses" => new()
        {
            new(3, "Spaghetti Carbonara", "Traditional Roman pasta with eggs, cheese, and pancetta."),
            new(4, "Grilled Salmon", "Fresh salmon fillet with lemon herb butter."),
        },
        "desserts" => new()
        {
            new(5, "Chocolate Lava Cake", "Rich molten chocolate cake with a gooey center."),
            new(6, "Tiramisu", "Classic Italian coffee-flavored layered dessert."),
        },
        _ => new()
    };

    private record RecipeInfo(int Id, string Title, string Description);
}

@page "/recipe/{Id:int}"

<PageTitle>@title - RecipeShare</PageTitle>

<h1>@title</h1>

@if (found)
{
    <h3>Ingredients</h3>
    <ul>
        @foreach (var ingredient in ingredients)
        {
            <li>@ingredient</li>
        }
    </ul>

    <h3>Steps</h3>
    <ol>
        @foreach (var step in steps)
        {
            <li>@step</li>
        }
    </ol>

    <h3>Rate This Recipe</h3>
    <StarRating RecipeId="Id" />
}
else
{
    <p>Recipe not found.</p>
}

<a href="/" class="btn btn-secondary mt-3">← Back to Home</a>

@code {
    [Parameter]
    public int Id { get; set; }

    private bool found;
    private string title = "";
    private List<string> ingredients = new();
    private List<string> steps = new();

    protected override void OnParametersSet()
    {
        var recipe = GetRecipe(Id);
        if (recipe is not null)
        {
            found = true;
            title = recipe.Title;
            ingredients = recipe.Ingredients;
            steps = recipe.Steps;
        }
    }

    private static RecipeData? GetRecipe(int id) => id switch
    {
        1 => new("Bruschetta",
            new() { "1 baguette, sliced", "4 tomatoes, diced", "Fresh basil", "2 cloves garlic", "Olive oil", "Salt and pepper" },
            new() { "Toast baguette slices until golden.", "Mix diced tomatoes with minced garlic, basil, olive oil, salt, and pepper.", "Spoon tomato mixture onto toasted bread.", "Serve immediately." }),
        2 => new("Spinach Dip",
            new() { "10 oz frozen spinach", "8 oz cream cheese", "1 can artichoke hearts", "1/2 cup parmesan", "2 cloves garlic" },
            new() { "Thaw and drain spinach thoroughly.", "Mix cream cheese, spinach, chopped artichokes, parmesan, and garlic.", "Bake at 350°F for 25 minutes until bubbly.", "Serve with bread or crackers." }),
        3 => new("Spaghetti Carbonara",
            new() { "400g spaghetti", "200g pancetta", "4 egg yolks", "100g pecorino romano", "Black pepper" },
            new() { "Cook spaghetti in salted boiling water until al dente.", "Fry pancetta until crispy.", "Whisk egg yolks with grated pecorino and pepper.", "Toss hot pasta with pancetta, then quickly stir in egg mixture off heat.", "Serve immediately with extra cheese." }),
        4 => new("Grilled Salmon",
            new() { "4 salmon fillets", "2 lemons", "Fresh dill", "3 tbsp butter", "Salt and pepper", "Garlic powder" },
            new() { "Season salmon with salt, pepper, and garlic powder.", "Grill skin-side down for 4-5 minutes, then flip.", "Cook 3-4 more minutes until flaky.", "Top with lemon herb butter and fresh dill." }),
        5 => new("Chocolate Lava Cake",
            new() { "200g dark chocolate", "100g butter", "3 eggs", "100g sugar", "30g flour", "Butter for ramekins" },
            new() { "Melt chocolate and butter together.", "Whisk eggs and sugar until fluffy.", "Fold chocolate mixture into eggs, then fold in flour.", "Pour into buttered ramekins.", "Bake at 425°F for 12-14 minutes.", "Invert onto plates and serve immediately." }),
        6 => new("Tiramisu",
            new() { "6 egg yolks", "500g mascarpone", "300ml strong espresso", "Ladyfinger biscuits", "Cocoa powder", "2 tbsp rum (optional)" },
            new() { "Whisk egg yolks with sugar until pale and thick.", "Fold in mascarpone until smooth.", "Mix espresso with rum and let cool.", "Dip ladyfingers briefly in espresso mixture.", "Layer soaked biscuits and mascarpone cream in a dish.", "Refrigerate at least 4 hours.", "Dust with cocoa powder before serving." }),
        _ => null
    };

    private record RecipeData(string Title, List<string> Ingredients, List<string> Steps);
}

@page "/submit"
@rendermode InteractiveServer

<PageTitle>Submit a Recipe - RecipeShare</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (submitted)
{
    <div class="alert alert-success">
        <strong>Thank you!</strong> Your recipe "@Model.Title" has been submitted successfully.
    </div>
    <button class="btn btn-primary" @onclick="Reset">Submit Another</button>
}
else
{
    <EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
        <DataAnnotationsValidator />
        <ValidationSummary />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" @bind-Value="Model.Title" class="form-control" placeholder="e.g., Grandma's Apple Pie" />
            <ValidationMessage For="() => Model.Title" />
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients (one per line)</label>
            <InputTextArea id="ingredients" @bind-Value="Model.Ingredients" class="form-control" rows="6"
                placeholder="2 cups flour&#10;1 cup sugar&#10;3 apples, sliced" />
            <ValidationMessage For="() => Model.Ingredients" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps (one per line)</label>
            <InputTextArea id="steps" @bind-Value="Model.Steps" class="form-control" rows="6"
                placeholder="Preheat oven to 375°F.&#10;Mix dry ingredients.&#10;Add wet ingredients." />
            <ValidationMessage For="() => Model.Steps" />
        </div>

        <button type="submit" class="btn btn-success">Submit Recipe</button>
    </EditForm>
}

<a href="/" class="btn btn-secondary mt-3">← Back to Home</a>

@code {
    private RecipeModel Model { get; set; } = new();
    private bool submitted;

    private void HandleSubmit()
    {
        submitted = true;
    }

    private void Reset()
    {
        Model = new();
        submitted = false;
    }

    private class RecipeModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Title is required.")]
        [System.ComponentModel.DataAnnotations.StringLength(100, ErrorMessage = "Title must be under 100 characters.")]
        public string Title { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please list the ingredients.")]
        public string Ingredients { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please list the steps.")]
        public string Steps { get; set; } = "";
    }
}

@rendermode InteractiveServer

<div class="star-rating" aria-label="Rate this recipe">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= currentRating ? "filled" : "")"
              @onclick="() => SetRating(star)"
              role="button"
              aria-label="@star stars">
            @(star <= currentRating ? "★" : "☆")
        </span>
    }
    @if (currentRating > 0)
    {
        <span class="ms-2 text-muted">You rated this @currentRating/5</span>
    }
</div>

<style>
    .star-rating .star {
        font-size: 1.8rem;
        cursor: pointer;
        color: #ccc;
        transition: color 0.15s;
    }
    .star-rating .star.filled {
        color: #ffc107;
    }
    .star-rating .star:hover {
        color: #ffdb4d;
    }
</style>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int currentRating;

    private void SetRating(int rating)
    {
        currentRating = rating;
    }
}

